/* ==========================================================================
   NetStore — Kılavuz içeriği

   Her metin üç dilde: { tr, en, fa }. Arayüz etiketleri **çift yıldız**
   içinde ve her dilde uygulamanın kendi sözlüğündeki (js/i18n.js) değerle
   BİREBİR aynıdır — kullanıcı kılavuzda gördüğü düğmeyi ekranda aynı adla
   bulsun diye. Etiketler docs-check betiğiyle sözlüğe karşı doğrulanır.

   Satır içi işaretler: **Etiket** · __vurgu__ · `değişmez değer` · A → B (menü yolu)
   ========================================================================== */

const L = (tr, en, fa) => ({ tr, en, fa });
const P = (tr, en, fa) => ({ type: 'p',    text: L(tr, en, fa) });
const H = (tr, en, fa) => ({ type: 'h',    text: L(tr, en, fa) });
const TIP  = (tr, en, fa) => ({ type: 'tip',  text: L(tr, en, fa) });
const WARN = (tr, en, fa) => ({ type: 'warn', text: L(tr, en, fa) });
const NOTE = (tr, en, fa) => ({ type: 'note', text: L(tr, en, fa) });
const S = (items) => ({ type: 'steps', items });
const U = (items) => ({ type: 'list',  items });
const T = (head, rows) => ({ type: 'table', head, rows });
/* Satır: üç dilde sütun listesi → sütun başına L nesnesi. */
const R = (tr, en, fa) => tr.map((_, i) => L(tr[i], en[i], fa[i]));

